SELECT toJSONString(groupArray(tuple(host,rows,represented_quotes))) AS payload FROM (SELECT hostName() AS host,count() AS rows,sum(n_quotes) AS represented_quotes FROM clusterAllReplicas(default,quotes_async_t4.quotes_daily) GROUP BY host ORDER BY host LIMIT 10) LIMIT 1 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=5000000,skip_unavailable_shards=1;
